```typescript
6	import { OrderStatus } from '@chunlv/shared';
7	import { logger } from '../common/logger';
8	
9	export const VALID_TRANSITIONS: Record<string, string[]> = {
10	  [OrderStatus.PENDING]: [OrderStatus.GRABBED, OrderStatus.CANCELLED],
11	  [OrderStatus.GRABBED]: [OrderStatus.CONFIRMED, OrderStatus.CANCELLED, OrderStatus.PENDING], // H2: allow re-pool
12	  [OrderStatus.CONFIRMED]: [OrderStatus.DONE, OrderStatus.CANCELLED],
13	};
14	
15	@Injectable()
16	export class OrderWorkflowService {
17	  constructor(
18	    private prisma: PrismaService,
19	    private wsGateway: WsGateway,
20	    private bridgeService: BridgeService,
21	  ) {}
22	
23	  validateTransition(order: { id: string; status: string }, targetStatus: string) {
24	    const allowed = VALID_TRANSITIONS[order.status];
25	    if (!allowed || !allowed.includes(targetStatus)) {
26	      throw new ForbiddenException(`不允许从 ${order.status} 转换到 ${targetStatus}`);
27	    }
28	  }
29	
30	  async grab(orderId: string, companionId: string) {
31	    const order = await this.prisma.order.findUnique({ where: { id: orderId } });
32	    if (!order) throw new NotFoundException('订单不存在');
33	    this.validateTransition(order, OrderStatus.GRABBED);
34	    if (order.dispatchType !== 'POOL' || order.companionId !== null) {
35	      throw new ForbiddenException('该订单不可抢');
36	    }
37	
38	    // Cross-studio scope: companion can only grab from own or bridged studios
39	    const companion = await this.prisma.companion.findUnique({
40	      where: { id: companionId },
41	      select: { studioId: true },
42	    });
43	    if (!companion) throw new NotFoundException('陪玩不存在');
44	    if (companion.studioId && companion.studioId !== order.studioId) {
45	      const bridgedIds = await this.bridgeService.getBridgedStudioIds(companion.studioId);
46	      if (!bridgedIds.includes(order.studioId)) {
47	        throw new ForbiddenException('无权抢其他工作室的订单');
48	      }
49	    }
50	
51	    // Prevent self-grabbing: companion can't grab their own created order
52	    const comp = await this.prisma.companion.findUnique({ where: { id: companionId }, select: { userId: true } });
53	    if (comp && comp.userId === order.csUserId) {
54	      throw new ForbiddenException('不能抢自己发布的订单');
55	    }
