207	    companionId: string,
208	    dto: {
209	      customerCode?: string;
210	      firstOrder: { duration: number; price: number };
211	      hasRenew?: boolean;
212	      renewOrder?: { duration: number; price: number };
213	      gameName: string;
214	      type: string; // 'COMPANION' | 'ESCORT'
215	      screenshotUrl?: string;
216	      wechatId?: string;
217	      splitTo?: Array<{ companionId: string; amount: number }>;
218	    },
219	  ) {
220	    const order = await this.prisma.order.findUnique({ where: { id: orderId } });
221	    if (!order) throw new NotFoundException('订单不存在');
222	    // Ownership check: only the assigned companion can complete with billing
223	    if (order.companionId !== companionId) throw new ForbiddenException('无权操作此订单');
224	    this.validateTransition(order, OrderStatus.DONE);
225	
226	    // Detect customer type
227	    const customer = dto.customerCode
228	      ? await this.prisma.customer.findUnique({ where: { customerCode: dto.customerCode } })
229	      : await this.prisma.customer.findUnique({ where: { id: order.customerId } });
230	
231	    if (!customer) throw new NotFoundException('客户不存在');
232	
233	    const orderCount = await this.prisma.order.count({
234	      where: { customerId: customer.id, status: 'DONE' },
235	    });
236	
237	    const customerType = orderCount === 0 ? 'NEW' : 'REPURCHASE';
238	
239	    // Calculate totals
240	    const firstAmount = dto.firstOrder.duration * dto.firstOrder.price;
241	    const renewAmount = dto.hasRenew && dto.renewOrder ? dto.renewOrder.duration * dto.renewOrder.price : 0;
242	    const totalAmount = firstAmount + renewAmount;
243	    const totalDuration = dto.firstOrder.duration + (dto.renewOrder?.duration || 0);
244	
245	    // Update the main order as DONE
246	    const updatedOrder = await this.prisma.order.update({
247	      where: { id: orderId },
248	      data: {
249	        status: OrderStatus.DONE,
250	        type: customerType,
251	        amount: totalAmount,
252	        duration: totalDuration,
253	        gameName: dto.gameName,
254	        customFields: {
255	          ...((order.customFields as any) || {}),
256	          firstOrder: dto.firstOrder,
257	          renewOrder: dto.renewOrder || null,
258	          hasRenew: dto.hasRenew || false,
259	          customerType,
260	          settlementType: dto.type,
261	          screenshotUrl: dto.screenshotUrl,
262	          wechatId: dto.wechatId,
263	          splits: (dto.splitTo || []).length > 0 ? dto.splitTo : undefined,
264	        },
265	      },
266	    });
267	
268	    // If hasRenew, create a separate RENEW order
269	    if (dto.hasRenew && dto.renewOrder) {
270	      await this.prisma.order.create({
271	        data: {
272	          type: 'RENEW',
273	          studioId: order.studioId,
274	          csUserId: order.csUserId,
275	          companionId,
276	          customerId: order.customerId,
277	          dispatchType: 'DIRECT',
278	          status: OrderStatus.DONE,
279	          amount: renewAmount,
280	          gameName: dto.gameName,
281	          duration: dto.renewOrder.duration,
282	          customFields: { parentOrderId: orderId },
283	        },
284	      });
285	    }
286	
287	    // Update revenue (C2 fix: unified entry — only complete paths record revenue)
288	    try {
289	      await this.prisma.customer.update({
290	        where: { id: customer.id },
291	        data: { totalSpent: { increment: totalAmount } },
292	      });
293	      // Calculate split amounts
294	      const splitTotal = (dto.splitTo || []).reduce((s, e) => s + e.amount, 0);
295	      const primaryAmount = totalAmount - splitTotal;
296	      await this.prisma.companion.update({
297	        where: { id: companionId },
298	        data: { monthlyRevenue: { increment: primaryAmount } },
299	      });
300	      // Record revenue for split companions (cross-studio billing)
301	      for (const split of dto.splitTo || []) {
302	        try {
303	          await this.prisma.companion.update({
304	            where: { id: split.companionId },
305	            data: { monthlyRevenue: { increment: split.amount } },
306	          });
307	        } catch (err) {
308	          logger.error('Split revenue update failed', {
309	            error: (err as Error).message,
310	            splitCompanionId: split.companionId,
311	          });
312	        }
313	      }
314	    } catch (err) {
315	      logger.error('Revenue update failed', { error: (err as Error).message });
316	    }
317	
318	    // Auto-assign customer to companion if not yet assigned
319	    try {
320	      await this.prisma.customer.updateMany({
321	        where: { id: customer.id, companionId: null },
322	        data: { companionId },
323	      });
324	    } catch (err) {
325	      logger.error('Customer assignment failed during completeWithBilling', { error: (err as Error).message });
326	    }
327	
328	    // Update customer status
329	    await this.prisma.customer.update({
330	      where: { id: customer.id },
331	      data: { status: 'ACTIVE' },
332	    });
333	
334	    this.wsGateway.broadcastToBridgedStudios(updatedOrder.studioId, 'order:pool_updated', updatedOrder);
335	    return updatedOrder;
336	  }
337	
338	  async cancel(orderId: string, userStudioId?: string, companionId?: string, role?: string) {
339	    const order = await this.prisma.order.findUnique({ where: { id: orderId } });
340	    if (!order) throw new NotFoundException('订单不存在');
341	    // COMPANION can only cancel their own orders
342	    if (role === 'COMPANION') {
343	      if (order.companionId !== companionId) throw new ForbiddenException('只能取消自己的订单');
344	    } else if (userStudioId) {
345	      // CS/ADMIN can only cancel orders in their own studio or bridged studios
346	      const visibleIds = await this.bridgeService.getVisibleStudioIds(userStudioId);
347	      if (!visibleIds.includes(order.studioId)) throw new ForbiddenException('无权操作其他工作室的订单');
348	    }
349	    this.validateTransition(order, OrderStatus.CANCELLED);
350	    const updated = await this.prisma.order.update({
351	      where: { id: orderId },
352	      data: { status: OrderStatus.CANCELLED },
353	    });
354	    this.wsGateway.broadcastToBridgedStudios(updated.studioId, 'order:pool_updated', updated);
355	    if (updated.companionId) {
356	      this.wsGateway.pushOrder(updated.companionId, updated);
357	    }
358	    return updated;
359	  }
360	}
