3	import { UserRole } from '@chunlv/shared';
4	
5	export const ROLES_KEY = 'roles';
6	export const Roles = (...roles: UserRole[]) => SetMetadata(ROLES_KEY, roles);
7	
8	/** Roles that require authorization (isAuthorized check) */
9	const ROLES_REQUIRING_AUTH: UserRole[] = [UserRole.CS, UserRole.COMPANION, UserRole.ADMIN];
10	
11	@Injectable()
12	export class RolesGuard implements CanActivate {
13	  constructor(private readonly reflector: Reflector) {}
14	
15	  canActivate(context: ExecutionContext): boolean {
16	    const requiredRoles = this.reflector.getAllAndOverride<UserRole[]>(ROLES_KEY, [
17	      context.getHandler(),
18	      context.getClass(),
19	    ]);
20	
21	    if (!requiredRoles || requiredRoles.length === 0) {
22	      return true;
23	    }
24	
25	    const { user } = context.switchToHttp().getRequest();
26	    if (!user) {
27	      return false;
28	    }
29	
30	    if (!requiredRoles.includes(user.role)) {
31	      throw new ForbiddenException('无权访问');
32	    }
33	
34	    // isAuthorized check: CS and COMPANION must be approved
35	    if (ROLES_REQUIRING_AUTH.includes(user.role) && !user.isAuthorized) {
36	      throw new ForbiddenException('账号尚未通过审核，请联系管理员');
37	    }
38	
39	    return true;
40	  }
