app.whenReady().then(() => {
  // Handle app:// protocol
  protocol.handle('app', (request) => {
    const url = request.url.replace('app://', '');
    const filePath = path.join(__dirname, '..', url);
    return net.fetch('file://' + filePath);
  });
  Menu.setApplicationMenu(null);
  app.setLoginItemSettings({ openAtLogin: true });
  logger.info('Electron app started', { version: app.getVersion() });
  setupIPC();
  setupWsEvents();
  mainWindow = createMainWindow();
  floatWindow = createFloatBall();

  // On first launch (no saved token), show the window so the user can log in.
  // On subsequent auto-starts, hide to system tray.
  const token = store.get('token') as string;
  if (token) {
    mainWindow.hide();
  }
  // else: window will show after ready-to-show event

  createTray({
    onShow: () => {
      mainWindow?.show();
      mainWindow?.focus();
    },
    onQuit: () => {
      isQuitting = true;
      app.quit();
    },
  });

  if (token) {
    connectWebSocket(getServerUrl(), token, store.get('companionId') as string);

    // Start blacklist polling via REST (works even when WS disconnected)
