7	  onOrderGrabbed?: (data: any) => void;
8	  onOrderNew?: (data: any) => void;
9	  onOrderUrgent?: (data: any) => void;
10	  onStatusBroadcast?: (data: any) => void;
11	  // Legacy chat events (deprecated, remove after migration)
12	  onChatNotify?: (data: any) => void;
13	  onChatNew?: (data: any) => void;
14	  onChatMessage?: (data: any) => void;
15	  // Chat 3.0 events
16	  onMessageNew?: (data: any) => void;
17	  onMessageUpdated?: (data: any) => void;
18	  onMessageAcked?: (data: any) => void;
19	  onTypingNotify?: (data: any) => void;
20	  onRoomUpdated?: (data: any) => void;
21	  onSyncRequired?: (data: any) => void;
22	  onPartnerCall?: (data: any) => void;
23	  onWalletReviewed?: (data: any) => void;
24	  onUserAuthorized?: (data: any) => void;
25	  onUserRejected?: (data: any) => void;
26	  onBridgeResponded?: (data: any) => void;
27	}
