29	export function useSocket(opts: UseSocketOptions = {}) {
30	  const socketRef = useRef<Socket | null>(null);
31	  const optsRef = useRef(opts);
32	  optsRef.current = opts;
33	
34	  useEffect(() => {
35	    const token = sessionStorage.getItem('accessToken');
36	    if (!token) return;
