  async reassign(
    @Param('id') id: string,
    @Body('companionId') companionId: string | null,
  ): Promise<ApiResponse<unknown>> {
    const data = await this.customersService.reassign(id, companionId);
    return { code: 200, message: 'ok', data };
  }

