      grouped[day].reports.push(r);
      grouped[day].totalAmount += r.amount || 0;
    });
    setDailyReports(Object.values(grouped).sort((a: any, b: any) => b.date.localeCompare(a.date)));
  } catch {}
}, [isAdmin]);

