  @Get('deploy/script')
  @UseGuards(AuthGuard('jwt'), RolesGuard)
  @Roles(UserRole.ADMIN, UserRole.OWNER, UserRole.CS)
  async getDeployScript(@Req() req: any): Promise<ApiResponse<unknown>> {
