// Watchdog process — monitors and auto-restarts the main app
const { spawn, exec } = require('child_process');
const path = require('path');
const fs = require('fs');

const MAIN_EXE = path.join(process.resourcesPath || path.dirname(process.execPath), '..', '蠢驴电竞.exe');
const CHECK_INTERVAL = 5000; // Check every 5 seconds

// Write PID file so main process knows watchdog is alive
const PID_FILE = path.join(process.env.TEMP || '/tmp', 'chunlv_watchdog.pid');
fs.writeFileSync(PID_FILE, String(process.pid));

function isMainRunning() {
  return new Promise((resolve) => {
    exec('tasklist /FI "IMAGENAME eq 蠢驴电竞.exe" /NH 2>nul', (err, stdout) => {
      resolve(stdout && stdout.includes('蠢驴电竞.exe'));
    });
  });
}

async function watch() {
  // Give the main app time to start
  await new Promise(r => setTimeout(r, 30000));

  while (true) {
    await new Promise(r => setTimeout(r, CHECK_INTERVAL));
    try {
      const running = await isMainRunning();
      if (!running) {
        // Main app was killed — restart it
        try {
          exec(`start "" "${MAIN_EXE}"`, { windowsHide: false });
        } catch {}
      }
    } catch {}
  }
}

watch();

